package com.example.lending.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.LocalDate;
import java.util.UUID;

@Entity
@Table(name = "loan")
public class LoanJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID bookId;

    @Column(nullable = false)
    private UUID memberId;

    @Column(nullable = false)
    private LocalDate loanedAt;

    @Column(nullable = false)
    private LocalDate dueAt;

    protected LoanJpaEntity() {
    }

    public LoanJpaEntity(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt) {
        this.id = id;
        this.bookId = bookId;
        this.memberId = memberId;
        this.loanedAt = loanedAt;
        this.dueAt = dueAt;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }
}
package com.example.lending.adapter.out.persistence;

import org.springframework.data.jpa.repository.JpaRepository;

import java.util.UUID;

public interface LoanJpaRepository extends JpaRepository<LoanJpaEntity, UUID> {

    long countByMemberId(UUID memberId);
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.Loan;

class LoanMapper {

    LoanJpaEntity toEntity(Loan loan) {
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(), loan.getDueAt());
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.CountActiveLoansPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.stereotype.Component;

import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements SaveLoanPort, CountActiveLoansPort {

    private final LoanJpaRepository loanJpaRepository;
    private final LoanMapper loanMapper = new LoanMapper();

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(loanMapper.toEntity(loan));
    }

    // 반납 기능이 아직 없으므로 회원의 모든 대출을 대출 중으로 본다
    @Override
    public long countActiveLoans(UUID memberId) {
        return loanJpaRepository.countByMemberId(memberId);
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.domain.Book;
import org.springframework.stereotype.Component;

import java.util.Optional;
import java.util.UUID;

@Component
public class BookPersistenceAdapter implements LoadBookPort, SaveBookPort {

    private final BookJpaRepository bookJpaRepository;
    private final BookMapper bookMapper = new BookMapper();

    public BookPersistenceAdapter(BookJpaRepository bookJpaRepository) {
        this.bookJpaRepository = bookJpaRepository;
    }

    @Override
    public Optional<Book> loadBook(UUID bookId) {
        return bookJpaRepository.findById(bookId).map(bookMapper::toDomain);
    }

    @Override
    public void saveBook(Book book) {
        bookJpaRepository.save(bookMapper.toEntity(book));
    }
}

